-- Coordenadas del archivo Escuelas.xlsx, vinculadas por clave provincial.
-- Cuatro coordenadas atípicas omitidas por indicación del usuario.
alter table public.escuelas add column latitud double precision, add column longitud double precision;
alter table public.escuelas add constraint escuelas_coordenadas_validas check (
  (latitud is null and longitud is null) or
  (latitud is not null and longitud is not null and latitud between -90 and 90 and longitud between -180 and 180)
);

